solution:
async function concurrencyLimit(tasks, limit) {
  const results = [];
  let idx = 0;
  async function runNext() {
    while (idx < tasks.length) {
      const i = idx++;
      results[i] = await tasks[i]();
    }
  }
  await Promise.all(Array.from({length: Math.min(limit, tasks.length)}, runNext));
  return results;
}

