solution:
function createEventEmitter() {
  const listeners = {};
  return {
    on: (event, fn) => {
      if (!listeners[event]) listeners[event] = [];
      listeners[event].push(fn);
    },
    emit: (event, ...args) => {
      (listeners[event]||[]).forEach(fn => fn(...args));
    },
    off: (event, fn) => {
      if (listeners[event]) listeners[event] = listeners[event].filter(f => f !== fn);
    }
  };
}

