  const calls = [];
  return function(...args) {
    const now = Date.now();
    while(calls.length && calls[0] <= now - timeWindow) calls.shift();
    if (calls.length >= maxCalls) throw new Error('Rate limit exceeded');
    calls.push(now);
    return fn(...args);
  };
}

